consumos_qa_mb_rules_inventario_navto_consultarinv_almacen_js,\n\tappconsumos_qa_mb_rules_inventario_navto_filtro_abast_js : appconsumos_qa_mb_rules_inventario_navto_filtro_abast_js,\n\tappconsumos_qa_mb_rules_inventario_navto_inventario_js : appconsumos_qa_mb_rules_inventario_navto_inventario_js,\n\tappconsumos_qa_mb_rules_inventario_navto_list_abastecimiento_js : appconsumos_qa_mb_rules_inventario_navto_list_abastecimiento_js,\n\tappconsumos_qa_mb_rules_inventario_navto_revisionalmacenes_js : appconsumos_qa_mb_rules_inventario_navto_revisionalmacenes_js,\n\tappconsumos_qa_mb_rules_inventario_navto_revisionsolicitudabast_js : appconsumos_qa_mb_rules_inventario_navto_revisionsolicitudabast_js,\n\tappconsumos_qa_mb_rules_inventario_onchange_materiales_revision_abast_js : appconsumos_qa_mb_rules_inventario_onchange_materiales_revision_abast_js,\n\tappconsumos_qa_mb_rules_inventario_query_confirmar_componentes_abast_js : appconsumos_qa_mb_rules_inventario_query_confirmar_componentes_abast_js,\n\tappconsumos_qa_mb_rules_inventario_query_detalle_componentes_abast_js : appconsumos_qa_mb_rules_inventario_query_detalle_componentes_abast_js,\n\tappconsumos_qa_mb_rules_inventario_query_detalle_componentes_abast_nuevo_js : appconsumos_qa_mb_rules_inventario_query_detalle_componentes_abast_nuevo_js,\n\tappconsumos_qa_mb_rules_inventario_query_lista_abast_js : appconsumos_qa_mb_rules_inventario_query_lista_abast_js,\n\tappconsumos_qa_mb_rules_inventario_query_revisar_abast_js : appconsumos_qa_mb_rules_inventario_query_revisar_abast_js,\n\tappconsumos_qa_mb_rules_inventario_rechazar_material_revision_abast_js : appconsumos_qa_mb_rules_inventario_rechazar_material_revision_abast_js,\n\tappconsumos_qa_mb_rules_inventario_rechazar_solicitud_abast_js : appconsumos_qa_mb_rules_inventario_rechazar_solicitud_abast_js,\n\tappconsumos_qa_mb_rules_inventario_redraw_list_revisar_js : appconsumos_qa_mb_rules_inventario_redraw_list_revisar_js,\n\tappconsumos_qa_mb_rules_inventario_select_almacen_filtro_inventario_js : appconsumos_qa_mb_rules_inventario_select_almacen_filtro_inventario_js,\n\tappconsumos_qa_mb_rules_inventario_select_almacen_sol_abast_js : appconsumos_qa_mb_rules_inventario_select_almacen_sol_abast_js,\n\tappconsumos_qa_mb_rules_inventario_select_material_revisar_abast_js : appconsumos_qa_mb_rules_inventario_select_material_revisar_abast_js,\n\tappconsumos_qa_mb_rules_inventario_set_visibleagregarmaterialexistente_js : appconsumos_qa_mb_rules_inventario_set_visibleagregarmaterialexistente_js,\n\tappconsumos_qa_mb_rules_inventario_set_visibleagregarmaterialnuevo_js : appconsumos_qa_mb_rules_inventario_set_visibleagregarmaterialnuevo_js,\n\tappconsumos_qa_mb_rules_inventario_setvisible_cantaprobadarevision_abast_js : appconsumos_qa_mb_rules_inventario_setvisible_cantaprobadarevision_abast_js,\n\tappconsumos_qa_mb_rules_inventario_setvisible_crearsolicitudabast_js : appconsumos_qa_mb_rules_inventario_setvisible_crearsolicitudabast_js,\n\tappconsumos_qa_mb_rules_inventario_target_lista_materiales_agregados_js : appconsumos_qa_mb_rules_inventario_target_lista_materiales_agregados_js,\n\tappconsumos_qa_mb_rules_inventario_target_materiales_revision_abast_js : appconsumos_qa_mb_rules_inventario_target_materiales_revision_abast_js,\n\tappconsumos_qa_mb_rules_inventario_target_revisar_almacenes_abast_js : appconsumos_qa_mb_rules_inventario_target_revisar_almacenes_abast_js,\n\tappconsumos_qa_mb_rules_inventario_validate_create_solicitud_abast_js : appconsumos_qa_mb_rules_inventario_validate_create_solicitud_abast_js,\n\tappconsumos_qa_mb_rules_logging_loglevels_js : appconsumos_qa_mb_rules_logging_loglevels_js,\n\tappconsumos_qa_mb_rules_logging_settracecategories_js : appconsumos_qa_mb_rules_logging_settracecategories_js,\n\tappconsumos_qa_mb_rules_logging_setuserloglevel_js : appconsumos_qa_mb_rules_logging_setuserloglevel_js,\n\tappconsumos_qa_mb_rules_logging_togglelogging_js : appconsumos_qa_mb_rules_logging_togglelogging_js,\n\tappconsumos_qa_mb_rules_logging_tracecategories_js : appconsumos_qa_mb_rules_logging_tracecategories_js,\n\tappconsumos_qa_mb_rules_logging_userlogsetting_js : appconsumos_qa_mb_rules_logging_userlogsetting_js,\n\tappconsumos_qa_mb_rules_rule_opendocumentoand_js : appconsumos_qa_mb_rules_rule_opendocumentoand_js,\n\tappconsumos_qa_mb_rules_rule_opendocumentoios_js : appconsumos_qa_mb_rules_rule_opendocumentoios_js,\n\tappconsumos_qa_mb_rules_service_initialize_js : appconsumos_qa_mb_rules_service_initialize_js,\n\tappconsumos_qa_mb_rules_set_visiblebtnautorizar_js : appconsumos_qa_mb_rules_set_visiblebtnautorizar_js,\n\tappconsumos_qa_mb_rules_set_visiblebtnconfirmar_js : appconsumos_qa_mb_rules_set_visiblebtnconfirmar_js,\n\tappconsumos_qa_mb_rules_set_visiblebtnnetear_js : appconsumos_qa_mb_rules_set_visiblebtnnetear_js,\n\tappconsumos_qa_mb_rules_set_visiblebtnrevisar_js : appconsumos_qa_mb_rules_set_visiblebtnrevisar_js,\n\tappconsumos_qa_mb_rules_zbodega_ago_srv_errorarchive_checkforsyncerror_js : appconsumos_qa_mb_rules_zbodega_ago_srv_errorarchive_checkforsyncerror_js,\n\tappconsumos_qa_mb_services_app_consumos_qa_service : appconsumos_qa_mb_services_app_consumos_qa_service,\n\tappconsumos_qa_mb_services_backend_rest_service : appconsumos_qa_mb_services_backend_rest_service,\n\tappconsumos_qa_mb_services_zamanage_logistic_service : appconsumos_qa_mb_services_zamanage_logistic_service,\n\tappconsumos_qa_mb_services_zbodega_ago_srv_service : appconsumos_qa_mb_services_zbodega_ago_srv_service,\n\tappconsumos_qa_mb_styles_styles_css : appconsumos_qa_mb_styles_styles_css,\n\tappconsumos_qa_mb_styles_styles_less : appconsumos_qa_mb_styles_styles_less,\n\tappconsumos_qa_mb_styles_styles_light_css : appconsumos_qa_mb_styles_styles_light_css,\n\tappconsumos_qa_mb_styles_styles_light_json : appconsumos_qa_mb_styles_styles_light_json,\n\tappconsumos_qa_mb_styles_styles_light_nss : appconsumos_qa_mb_styles_styles_light_nss,\n\tapplication_app : application_app,\n\ttsconfig_json : tsconfig_json,\n\tversion_mdkbundlerversion : version_mdkbundlerversion\n}","/**\n * Describe this function...\n * @param {IClientAPI} context\n */\nexport default function Agregar_Consumos_Revision(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Aceite_Motor').getClientData();\n    let registro_consumo_value = context.evaluateTargetPath('#Page:Revisar_Planilla_Aceite_Motor/#Control:registro_consumo/#Value');\n    let clmov_value = context.evaluateTargetPath('#Page:Revisar_Planilla_Aceite_Motor/#Control:orden_obj/#Value');\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\");\n    \n    if(registro_consumo_value.length < 1){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Consumo No Seleccionado\",\n                \"Message\": `Debes seleccionar un consumo para continuar`\n            }\n        });\n    }\n\n    if(clmov_value.length < 1){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Orden No Seleccionada\",\n                \"Message\": `Debes seleccionar una clase de movimiento para continuar`\n            }\n        });\n    }\n\n    let dataConsumo = registro_consumo_value[0].BindingObject\n    let clase_mov = clmov_value[0].ReturnValue\n    //tipoData = tipo[0].DisplayValue;\n    //tipoData = tipo[0].ReturnValue\n\n    const duplicado = clientData.lista_revision_motor.filter(m => m.pos === dataConsumo.pos).length > 0\n\n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Consumo No Agregado\",\n                \"Message\": `El consumo ya fue ingresado anteriormente`\n            }\n        });\n    }\n    \n    dataConsumo.clase_mov = clase_mov\n    clientData.lista_revision_motor.push(dataConsumo)\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Consumo agregado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Agregar_Consumos_Revision_Diferencial(context) {\n    const pageProxy = context.getPageProxy();\n    let clientData = context.evaluateTargetPathForAPI('#Page:Detalle_Aceite_Diferencial').getClientData();\n    let registro_consumo_value = context.evaluateTargetPath('#Page:Revisar_Planilla_Aceite_Diferencial/#Control:registro_consumo/#Value');\n    let clmov_value = context.evaluateTargetPath('#Page:Revisar_Planilla_Aceite_Diferencial/#Control:orden_obj/#Value');\n    var list_component = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionObjectTable0\");\n    \n    if(registro_consumo_value.length < 1){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Consumo No Seleccionado\",\n                \"Message\": `Debes seleccionar un consumo para continuar`\n            }\n        });\n    }\n\n    if(clmov_value.length < 1){\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Orden No Seleccionada\",\n                \"Message\": `Debes seleccionar una clase de movimiento para continuar`\n            }\n        });\n    }\n\n    let dataConsumo = registro_consumo_value[0].BindingObject\n    let clase_mov = clmov_value[0].ReturnValue\n    //tipoData = tipo[0].DisplayValue;\n    //tipoData = tipo[0].ReturnValue\n\n    const duplicado = clientData.lista_revision_diferencial.filter(m => m.pos === dataConsumo.pos).length > 0\n\n    if (duplicado) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Consumo No Agregado\",\n                \"Message\": `El consumo ya fue ingresado anteriormente`\n            }\n        });\n    }\n    \n    dataConsumo.clase_mov = clase_mov\n    clientData.lista_revision_diferencial.push(dataConsumo)\n    list_component.redraw()\n    return context.executeAction({\n        \"Name\": \"/appconsumos_qa_mb/Actions/GenericToastMessage.action\",\n        \"Properties\": {\n            \"Message\": `Consumo agregado`,\n            \"Duration\": 1,\n            \"ShowActivityIndicator\": true,\n        }\n    });\n}\n","/**\n * Agregar Planilla Aceites - Con validación de duplicados y aceite reductor\n * @param {IClientAPI} context\n */\nexport default function Agregar_Planilla_Aceites(context) {\n    let fichaOperario = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_ficha/#Value');\n    // Validar si la ficha existe\n    if (!fichaOperario) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar el número de ficha para continuar`\n            }\n        });\n    }\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'EmpleadosApp', [], `$filter=ficha eq '${fichaOperario}'`).then((results) => {\n        if (!results || results.length === 0) {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Alerta\",\n                    \"Message\": `Número de ficha no encontrada. Debes ingresar un número de ficha válido para continuar`\n                }\n            });\n        }\n\n        let material_hidraulico = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_id_material/#Value');\n        let cant_hidraulico = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_cant_ini_hid/#Value');\n        let material_motor = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_id_mat_motor/#Value');\n        let cant_motor = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_cant_ini_motor/#Value');\n        let material_dif = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_id_mat_diferen/#Value');\n        let cant_dif = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_cant_ini_dif/#Value');\n        let material_reduc = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_id_mat_reduc/#Value');\n        let cant_reduc = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo/#Control:FormCellSimpleProperty_cant_ini_reduc/#Value');\n\n        let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n\n        // Inicializar lista si no existe\n        if (!clientData.lista_aceites) {\n            clientData.lista_aceites = [];\n        }\n\n        // Función para verificar si un material ya existe en la lista\n        function materialYaExiste(materialId) {\n            return clientData.lista_aceites.some(item => item.material === materialId);\n        }\n\n        // Función para obtener la descripción del material según el tipo\n        function obtenerDescripcionMaterial(tipo) {\n            const descripciones = {\n                'hidraulico': 'ACEITE HIDRAULICO 424 FLUID',\n                'motor': 'ACEITE MOBIL 15W-40 FULL PROTEC. MOTOR',\n                'diferencial': 'ACEITE MOBILUBE HD 85W-140',\n                'reductor': 'ACEITE MOBILUBE HD 80W-90 CAJA'\n            };\n            return descripciones[tipo] || '';\n        }\n\n        let materialesAgregados = [];\n        let materialesDuplicados = [];\n\n        // Agregar material hidráulico si tiene valor y no existe\n        if (material_hidraulico && cant_hidraulico) {\n            if (!materialYaExiste(material_hidraulico)) {\n                clientData.lista_aceites.push({\n                    material: material_hidraulico,\n                    contador_ini: cant_hidraulico,\n                    material_desc: obtenerDescripcionMaterial('hidraulico')\n                });\n                materialesAgregados.push(`Hidráulico: ${material_hidraulico}`);\n            } else {\n                materialesDuplicados.push(`Hidráulico: ${material_hidraulico}`);\n            }\n        }\n\n        // Agregar material motor si tiene valor y no existe\n        if (material_motor && cant_motor) {\n            if (!materialYaExiste(material_motor)) {\n                clientData.lista_aceites.push({\n                    material: material_motor,\n                    contador_ini: cant_motor,\n                    material_desc: obtenerDescripcionMaterial('motor')\n                });\n                materialesAgregados.push(`Motor: ${material_motor}`);\n            } else {\n                materialesDuplicados.push(`Motor: ${material_motor}`);\n            }\n        }\n\n        // Agregar material diferencial si tiene valor y no existe\n        if (material_dif && cant_dif) {\n            if (!materialYaExiste(material_dif)) {\n                clientData.lista_aceites.push({\n                    material: material_dif,\n                    contador_ini: cant_dif,\n                    material_desc: obtenerDescripcionMaterial('diferencial')\n                });\n                materialesAgregados.push(`Diferencial: ${material_dif}`);\n            } else {\n                materialesDuplicados.push(`Diferencial: ${material_dif}`);\n            }\n        }\n\n        // Agregar material reductor si tiene valor y no existe\n        if (material_reduc && cant_reduc) {\n            if (!materialYaExiste(material_reduc)) {\n                clientData.lista_aceites.push({\n                    material: material_reduc,\n                    contador_ini: cant_reduc,\n                    material_desc: obtenerDescripcionMaterial('reductor')\n                });\n                materialesAgregados.push(`Reductor: ${material_reduc}`);\n            } else {\n                materialesDuplicados.push(`Reductor: ${material_reduc}`);\n            }\n        }\n\n        let cantidadRequerida = 4; // Hidráulico, Motor, Diferencial, Reductor\n        let cantidadActual = clientData.lista_aceites.length;\n\n        //Verificar primero si ya está completa la lista\n        if (cantidadActual >= cantidadRequerida) {\n            // Lista ya completa - ir directamente a confirmación de creación\n            let mensaje = \"Lista completa. ¿Deseas crear las planillas?\";\n\n            if (materialesDuplicados.length > 0) {\n                mensaje = `Los materiales fueron agregados correctamente.\\nLista completa (${cantidadActual}/${cantidadRequerida}). ¿Deseas crear las planillas?`;\n            }\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Confirmación\",\n                    \"Message\": mensaje,\n                    \"OKCaption\": \"Aceptar\",\n                    \"OnOK\": \"/appconsumos_qa_mb/Rules/Aceites/Crear_Planillas_Aceites.js\",\n                    \"CancelCaption\": \"Cancelar\"\n                }\n            });\n        }\n\n        // Si hay materiales duplicados pero la lista NO está completa\n        if (materialesDuplicados.length > 0) {\n            let mensajeDuplicados = `Los siguientes materiales ya han sido agregados:\\n${materialesDuplicados.join('\\n')}`;\n\n            if (materialesAgregados.length > 0) {\n                mensajeDuplicados += `\\n\\nNuevos materiales agregados:\\n${materialesAgregados.join('\\n')}`;\n            }\n\n            mensajeDuplicados += `\\n\\nMateriales en lista: ${cantidadActual}/${cantidadRequerida}`;\n\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Materiales duplicados\",\n                    Message: mensajeDuplicados,\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Si se agregaron materiales y ahora la lista está completa\n        if (materialesAgregados.length > 0 && cantidadActual >= cantidadRequerida) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Lista completa\",\n                    Message: `Se agregaron:\\n${materialesAgregados.join('\\n')}\\n\\nLista completa (${cantidadActual}/${cantidadRequerida}). Creando planillas...`,\n                    CloseCaption: \"Continuar\"\n                }\n            }).then(() => {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Confirmación\",\n                        \"Message\": \"¿Estás seguro de que deseas crear las planillas?\",\n                        \"OKCaption\": \"Aceptar\",\n                        \"OnOK\": \"/appconsumos_qa_mb/Rules/Aceites/Crear_Planillas_Aceites.js\",\n                        \"CancelCaption\": \"Cancelar\"\n                    }\n                });\n            });\n        }\n\n        // Si se agregaron materiales pero la lista aún está incompleta\n        if (materialesAgregados.length > 0) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Materiales agregados\",\n                    Message: `Se agregaron:\\n${materialesAgregados.join('\\n')}\\n\\nProgreso: ${cantidadActual}/${cantidadRequerida}\\nFaltan ${cantidadRequerida - cantidadActual} materiales más.`,\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Si no se agregó nada nuevo y la lista está incompleta\n        return context.executeAction({\n            Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            Properties: {\n                Title: \"Lista incompleta\",\n                Message: `Materiales en lista: ${cantidadActual}/${cantidadRequerida}\\nDebe agregar ${cantidadRequerida - cantidadActual} materiales más para continuar.`,\n                CloseCaption: \"Cerrar\"\n            }\n        });\n\n    }).catch((error) => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Error\",\n                \"Message\": `Error al validar la ficha: ${error.message}`,\n                \"CloseCaption\": \"Cerrar\"\n            }\n        });\n    });\n}","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Agregar_Planilla_Aceites_Incauca(context) {\n    let fichaOperario = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo_Incauca/#Control:FormCellSimpleProperty_ficha/#Value');\n    // Validar si la ficha existe\n    if (!fichaOperario) {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Alerta\",\n                \"Message\": `Debes ingresar el número de ficha para continuar`\n            }\n        });\n    }\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'EmpleadosApp', [], `$filter=ficha eq '${fichaOperario}'`).then((results) => {\n        if (!results || results.length === 0) {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Alerta\",\n                    \"Message\": `Número de ficha no encontrada. Debes ingresar un número de ficha válido para continuar`\n                }\n            });\n        }\n\n        let material_hidraulico = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo_Incauca/#Control:FormCellSimpleProperty_id_material/#Value');\n        let cant_hidraulico = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo_Incauca/#Control:FormCellSimpleProperty_cant_ini_hid/#Value');\n        let material_motor = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo_Incauca/#Control:FormCellSimpleProperty_id_mat_motor/#Value');\n        let cant_motor = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo_Incauca/#Control:FormCellSimpleProperty_cant_ini_motor/#Value');\n        let material_dif = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo_Incauca/#Control:FormCellSimpleProperty_id_mat_diferen/#Value');\n        let cant_dif = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo_Incauca/#Control:FormCellSimpleProperty_cant_ini_dif/#Value');\n        let material_reduc = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo_Incauca/#Control:FormCellSimpleProperty_id_mat_reduc/#Value');\n        let cant_reduc = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo_Incauca/#Control:FormCellSimpleProperty_cant_ini_reduc/#Value');\n        let material_servo = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo_Incauca/#Control:FormCellSimpleProperty_id_mat_servotrans/#Value');\n        let cant_servo = context.evaluateTargetPath('#Page:Crear_Planilla_Consumo_Incauca/#Control:FormCellSimpleProperty_cant_ini_servotrans/#Value');\n\n        let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n\n        // Inicializar lista si no existe\n        if (!clientData.lista_aceites) {\n            clientData.lista_aceites = [];\n        }\n\n        // Función para verificar si un material ya existe en la lista\n        function materialYaExiste(materialId) {\n            return clientData.lista_aceites.some(item => item.material === materialId);\n        }\n\n        // Función para obtener la descripción del material según el tipo\n        function obtenerDescripcionMaterial(tipo) {\n            const descripciones = {\n                'hidraulico': 'ACEITE HIDRAULICO 424 FLUID',\n                'motor': 'ACEITE MOBIL 15W-40 FULL PROTEC. MOTOR',\n                'diferencial': 'ACEITE MOBILUBE HD 85W-140',\n                'reductor': 'ACEITE MOBILUBE HD 80W-90 CAJA',\n                'servotrans': 'ACEITE M-MOBILTRANS HD 30 DRUM-L',\n            };\n            return descripciones[tipo] || '';\n        }\n\n        let materialesAgregados = [];\n        let materialesDuplicados = [];\n\n        // Agregar material hidráulico si tiene valor y no existe\n        if (material_hidraulico && cant_hidraulico) {\n            if (!materialYaExiste(material_hidraulico)) {\n                clientData.lista_aceites.push({\n                    material: material_hidraulico,\n                    contador_ini: cant_hidraulico,\n                    material_desc: obtenerDescripcionMaterial('hidraulico')\n                });\n                materialesAgregados.push(`Hidráulico: ${material_hidraulico}`);\n            } else {\n                materialesDuplicados.push(`Hidráulico: ${material_hidraulico}`);\n            }\n        }\n\n        // Agregar material motor si tiene valor y no existe\n        if (material_motor && cant_motor) {\n            if (!materialYaExiste(material_motor)) {\n                clientData.lista_aceites.push({\n                    material: material_motor,\n                    contador_ini: cant_motor,\n                    material_desc: obtenerDescripcionMaterial('motor')\n                });\n                materialesAgregados.push(`Motor: ${material_motor}`);\n            } else {\n                materialesDuplicados.push(`Motor: ${material_motor}`);\n            }\n        }\n\n        // Agregar material diferencial si tiene valor y no existe\n        if (material_dif && cant_dif) {\n            if (!materialYaExiste(material_dif)) {\n                clientData.lista_aceites.push({\n                    material: material_dif,\n                    contador_ini: cant_dif,\n                    material_desc: obtenerDescripcionMaterial('diferencial')\n                });\n                materialesAgregados.push(`Diferencial: ${material_dif}`);\n            } else {\n                materialesDuplicados.push(`Diferencial: ${material_dif}`);\n            }\n        }\n\n        // Agregar material reductor si tiene valor y no existe\n        if (material_reduc && cant_reduc) {\n            if (!materialYaExiste(material_reduc)) {\n                clientData.lista_aceites.push({\n                    material: material_reduc,\n                    contador_ini: cant_reduc,\n                    material_desc: obtenerDescripcionMaterial('reductor')\n                });\n                materialesAgregados.push(`Reductor: ${material_reduc}`);\n            } else {\n                materialesDuplicados.push(`Reductor: ${material_reduc}`);\n            }\n        }\n\n        // Agregar material servotrans si tiene valor y no existe\n        if (material_servo && cant_servo) {\n            if (!materialYaExiste(material_servo)) {\n                clientData.lista_aceites.push({\n                    material: material_servo,\n                    contador_ini: cant_servo,\n                    material_desc: obtenerDescripcionMaterial('reductor')\n                });\n                materialesAgregados.push(`Servotransmisión: ${material_servo}`);\n            } else {\n                materialesDuplicados.push(`Servotransmisión: ${material_servo}`);\n            }\n        }\n\n        let cantidadRequerida = 5; // Hidráulico, Motor, Diferencial, Reductor, Servotransmisión\n        let cantidadActual = clientData.lista_aceites.length;\n\n        //Verificar primero si ya está completa la lista\n        if (cantidadActual >= cantidadRequerida) {\n            // Lista ya completa - ir directamente a confirmación de creación\n            let mensaje = \"Lista completa. ¿Deseas crear las planillas?\";\n\n            if (materialesDuplicados.length > 0) {\n                mensaje = `Los materiales fueron agregados correctamente.\\nLista completa (${cantidadActual}/${cantidadRequerida}). ¿Deseas crear las planillas?`;\n            }\n\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Confirmación\",\n                    \"Message\": mensaje,\n                    \"OKCaption\": \"Aceptar\",\n                    \"OnOK\": \"/appconsumos_qa_mb/Rules/Aceites/Crear_Planillas_Aceites_Incauca.js\",\n                    \"CancelCaption\": \"Cancelar\"\n                }\n            });\n        }\n\n        // Si hay materiales duplicados pero la lista NO está completa\n        if (materialesDuplicados.length > 0) {\n            let mensajeDuplicados = `Los siguientes materiales ya han sido agregados:\\n${materialesDuplicados.join('\\n')}`;\n\n            if (materialesAgregados.length > 0) {\n                mensajeDuplicados += `\\n\\nNuevos materiales agregados:\\n${materialesAgregados.join('\\n')}`;\n            }\n\n            mensajeDuplicados += `\\n\\nMateriales en lista: ${cantidadActual}/${cantidadRequerida}`;\n\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Materiales duplicados\",\n                    Message: mensajeDuplicados,\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Si se agregaron materiales y ahora la lista está completa\n        if (materialesAgregados.length > 0 && cantidadActual >= cantidadRequerida) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Lista completa\",\n                    Message: `Se agregaron:\\n${materialesAgregados.join('\\n')}\\n\\nLista completa (${cantidadActual}/${cantidadRequerida}). Creando planillas...`,\n                    CloseCaption: \"Continuar\"\n                }\n            }).then(() => {\n                return context.executeAction({\n                    \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                    \"Properties\": {\n                        \"Title\": \"Confirmación\",\n                        \"Message\": \"¿Estás seguro de que deseas crear las planillas?\",\n                        \"OKCaption\": \"Aceptar\",\n                        \"OnOK\": \"/appconsumos_qa_mb/Rules/Aceites/Crear_Planillas_Aceites_Incauca.js\",\n                        \"CancelCaption\": \"Cancelar\"\n                    }\n                });\n            });\n        }\n\n        // Si se agregaron materiales pero la lista aún está incompleta\n        if (materialesAgregados.length > 0) {\n            return context.executeAction({\n                Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                Properties: {\n                    Title: \"Materiales agregados\",\n                    Message: `Se agregaron:\\n${materialesAgregados.join('\\n')}\\n\\nProgreso: ${cantidadActual}/${cantidadRequerida}\\nFaltan ${cantidadRequerida - cantidadActual} materiales más.`,\n                    CloseCaption: \"Cerrar\"\n                }\n            });\n        }\n\n        // Si no se agregó nada nuevo y la lista está incompleta\n        return context.executeAction({\n            Name: \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            Properties: {\n                Title: \"Lista incompleta\",\n                Message: `Materiales en lista: ${cantidadActual}/${cantidadRequerida}\\nDebe agregar ${cantidadRequerida - cantidadActual} materiales más para continuar.`,\n                CloseCaption: \"Cerrar\"\n            }\n        });\n\n    }).catch((error) => {\n        return context.executeAction({\n            \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n            \"Properties\": {\n                \"Title\": \"Error\",\n                \"Message\": `Error al validar la ficha: ${error.message}`,\n                \"CloseCaption\": \"Cerrar\"\n            }\n        });\n    });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Cerrar_Planilla_Aceite_Diferencial(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_diferencial.id;\n    let filtro = `$filter=id eq ${id_planilla}`;\n    let pageProxy = context.getPageProxy();\n    //acceder al keyvalue section\n    var keyvalueSection = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionKeyValue0\")\n   \n    var btn_agregar = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionButtonTable0\")\n    var form_add = pageProxy.getControl(\"SectionedTable0\").getSection(\"SectionFormCell0\")\n\n    return context.read('/appconsumos_qa_mb/Services/app_consumos_qa.service', 'PlanillasAceites', [], filtro).then(async (results) => {\n        if (results && results.length > 0) {\n            \n            clientData.data_planilla_diferencial.total = results.getItem(0).total;\n            clientData.data_planilla_diferencial.contador_fin = results.getItem(0).contador_fin;\n            clientData.data_planilla_diferencial.estado = results.getItem(0).estado;\n\n            btn_agregar.setVisible(false)\n            form_add.setVisible(false)\n            keyvalueSection.redraw();\n            pageProxy.redraw();\n\n        } else {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Sin datos\",\n                    \"Message\": \"No se encontró la planilla\",\n                    \"OKCaption\": \"Aceptar\"\n                }\n            });\n        }\n    })\n        .catch((error) => {\n            return context.executeAction({\n                \"Name\": \"/appconsumos_qa_mb/Actions/GenericMessageBox.action\",\n                \"Properties\": {\n                    \"Title\": \"Error\",\n                    \"Message\": `Error al consultar datos: ${error.message}`,\n                    \"OKCaption\": \"Cerrar\"\n                }\n            });\n        });\n}\n","/**\n * Describe this function...\n * @param {IClientAPI} clientAPI\n */\nexport default function Cerrar_Planilla_Aceite_Hidraulico(context) {\n    let clientData = context.evaluateTargetPathForAPI('#Page:Filtro_Aceites').getClientData();\n    let id_planilla = clientData.data_planilla_hidraulico.id;\n    let filtro = `$filter=id eq ${id_planilla}`;\n    let pageProxy = context.getPageProxy();\n    //acceder al keyvalue section\n    var keyvalueSection = pageProxy.getControl(